    const me = s && s.entrants.find(e => e.wallet === forWallet);
    out.youRegistered = !!me; out.youReady = !!(me && me.ready);
    out.yourPrize = cupPrizes.get(forWallet) || 0;
    out.youPlace = (s && s.place) ? (s.place[forWallet] || null) : null;
