export function _setTxConfirmedStubForTest(fn) { _txConfirmStub = (typeof fn === "function") ? fn : null; }
async function txMarketSplit(sig, buyer, seller, price) {
  try {
    const tx = await _txConfirmed(sig);
    if (!tx) return { ok: false, reason: "transaction not confirmed yet — it may still be settling; retry in a moment", pending: true };
    if (tx.meta && tx.meta.err) return { ok: false, reason: "the transaction failed on-chain" };
    const mint = MINT.toBase58(), teamStr = TEAM_WALLET;
    const pre = (tx.meta && tx.meta.preTokenBalances) || [], post = (tx.meta && tx.meta.postTokenBalances) || [];
    const amt = (arr, owner) => { const e = arr.find(b => b.owner === owner && b.mint === mint); return e ? Number((e.uiTokenAmount && e.uiTokenAmount.uiAmount) || 0) : 0; };
    const dSeller = amt(post, seller) - amt(pre, seller);
    const dTeam   = amt(post, teamStr) - amt(pre, teamStr);
    const dBuyer  = amt(pre, buyer) - amt(post, buyer);          // positive = spent
    // sum any REAL burn of the $CHIKI mint in this tx (top-level + inner instructions) so the 5%
    // can't be quietly redirected to an alt wallet — it must actually leave circulation
    let burned = 0;
    const scanBurn = (ixs) => { for (const ix of (ixs || [])) {
      const pr = ix && ix.parsed; if (!pr) continue;
      if (ix.program !== "spl-token" && ix.program !== "spl-token-2022") continue;
      if ((pr.type === "burn" || pr.type === "burnChecked") && pr.info && pr.info.mint === mint) {
        const ta = pr.info.tokenAmount;
        burned += ta ? Number(ta.uiAmount || 0) : Number(pr.info.amount || 0) / Math.pow(10, CHIKI_DECIMALS);
      }
    } };
    scanBurn(tx.transaction && tx.transaction.message && tx.transaction.message.instructions);
    for (const inner of ((tx.meta && tx.meta.innerInstructions) || [])) scanBurn(inner.instructions);
    // ============ TOLERANCE IS PER LEG, AND NEVER LARGER THAN THE LEG IT TOLERATES ============
    // It used to be ONE absolute figure — `min(25, max(2, price*0.001))` — subtracted from all four
    // checks, so on a cheap listing the slack SWALLOWED the requirement: at price 2 every leg's
    // adjusted floor was <= 0, and at price 10 the team leg's was 0.000 and the burn leg's -1.500.
    // Measured on a local fake RPC: a price-2 listing of 1400 GOLD was released for a total payment
    // of 0.000002 $CHIKI (status 200), and a price-10 buy settled while paying the 20% team tax and
    // the 5% burn 0.000001 each. Quantity is not part of the check, so the goods released were
    // unbounded — a sniping window on mis-priced listings and a fee-evasion window on cheap ones.
    //
    // WHAT THE SLACK IS ACTUALLY FOR, and it is the only thing it is for: Market.gd:1001-1003 puts
    // WHOLE tokens on chain — pool = round(price*0.20), burn = round(price*0.05), seller = price -
    // pool - burn — so each of team/burn can land up to 0.5 short of its exact share and the seller,
    // absorbing both remainders, up to 1.0. Those are the real bounds; anything beyond them was
    // never rounding. Each leg is additionally capped at HALF ITS OWN REQUIREMENT so the tolerance
    // can never exceed what it is tolerating (the price-29 burn leg legitimately needs 1.45 and gets
    // 1, i.e. 31% short — hence half, not a token percentage).
    const legTol = (need, cap) => Math.min(cap, Math.max(0, need) * 0.5);
    if (dBuyer <= 0 || dSeller <= 0 || dTeam <= 0 || burned <= 0) return { ok: false, reason: "no $CHIKI actually moved on one of the legs" };
    if (dBuyer  < price * 1.0                 - legTol(price * 1.0, 1.0))                 return { ok: false, reason: `buyer paid ${dBuyer}, need ${price}` };
    if (dSeller < price * MARKET_SELLER_SHARE - legTol(price * MARKET_SELLER_SHARE, 1.5)) return { ok: false, reason: `seller got ${dSeller}, need ${price * MARKET_SELLER_SHARE}` };
    if (dTeam   < price * MARKET_TEAM_TAX     - legTol(price * MARKET_TEAM_TAX, 1.0))     return { ok: false, reason: `team wallet got ${dTeam}, need ${price * MARKET_TEAM_TAX}` };
    if (burned  < price * MARKET_BURN         - legTol(price * MARKET_BURN, 1.0))         return { ok: false, reason: `only ${burned} $CHIKI burned, need ${price * MARKET_BURN}` };
    return { ok: true, seller: dSeller, team: dTeam, spent: dBuyer, burned };
  } catch (e) { return { ok: false, reason: "rpc error verifying transfer" }; }
}
// verify sig is a confirmed SPL transfer of >= amount of the $CHIKI mint from `from` to `to`
async function txTransfer(sig, from, to, amount) {
  try {
    const tx = await conn.getParsedTransaction(sig, { commitment: "confirmed", maxSupportedTransactionVersion: 0 });
    if (!tx || (tx.meta && tx.meta.err)) return false;
    const mint = MINT.toBase58();
    const pre = (tx.meta && tx.meta.preTokenBalances) || [], post = (tx.meta && tx.meta.postTokenBalances) || [];
    const amt = (arr, owner) => { const e = arr.find(b => b.owner === owner && b.mint === mint); return e ? Number((e.uiTokenAmount && e.uiTokenAmount.uiAmount) || 0) : 0; };
    const dTo = amt(post, to) - amt(pre, to);
    const dFrom = amt(post, from) - amt(pre, from);
    return dTo >= amount - 0.5 && dFrom <= -(amount - 0.5);
  } catch (e) { return false; }
}
app.post("/market/buy-onchain", async (req, res) => {
  if (!MARKET_ONCHAIN) return res.status(503).json({ error: "on-chain trading is not enabled yet — buys settle in in-game $CHIKI for now", onchain: false });
  const b = req.body || {};
  const buyer = String(b.buyer || "");
  const buyerName = stripTags(String(b.buyerName || "")).slice(0, 20);
  const sig = stripTags(String(b.txSig || "")).slice(0, 120);
  const id = stripTags(String(b.listingId || "")).slice(0, 40);
  if (!isPubkey(buyer)) return res.status(400).json({ error: "valid buyer wallet required" });
  if (!sig || !id) return res.status(400).json({ error: "txSig and listingId required" });
  // IDEMPOTENT RECOVERY: a re-POST of a sig already settled for THIS listing+buyer returns the same
  // release, so a buyer whose 200 was dropped can safely retry and still receive the goods. A sig
  // replayed against a DIFFERENT listing is refused — one payment settles exactly one item.
  const prior = _usedTxSigs.get(sig);
  if (prior) {
    if (prior.listingId === id && prior.buyer === buyer && prior.released) return res.json({ ok: true, released: prior.released, txSig: sig, replayed: true });
    return res.status(409).json({ error: "that transaction was already used" });
  }
  pruneMarket();
  const row = marketListings.find(x => x.id === id);
  if (!row) return res.status(404).json({ error: "listing is gone" });
  const sellerWallet = String(row.wallet || "");
  if (!isPubkey(sellerWallet)) return res.status(409).json({ error: "seller has no on-chain wallet on this listing" });
  if (sellerWallet === buyer) return res.status(400).json({ error: "that is your own listing" });
  // ============ ONE OF EACH, AND THE SATCHEL'S CAPACITY, ON THE BUY PATH (2026-08-18) ============
  // A chikimon listing is the one Trading Post good that is a CREATURE, and buying was the last
  // acquisition path with no ownership test at all: a wallet holding dragonos could buy a second
  // dragonos, which is the rule this ruling makes absolute. `kind` has never accepted "mount" or
  // "avatar" here (listItemOk), so chikimon is the whole surface.
  //
  // PLACED AS EARLY AS THE ROUTE ALLOWS — above the _usedTxSigs claim and above txMarketSplit — so
  // the refusal costs the buyer nothing that is recoverable any other way, and the listing stays on
  // the board for someone who can actually take it. It cannot be earlier than this in THIS file:
  // the money moves on chain before the server is ever called, which is why the client must not
  // offer the button (Market.gd reads the same rule) and why the sentence below names the recovery
  // in the same words the double-buy refusal uses.
  if (String(row.kind) === "chikimon") {
    const _cr = satchelCapRefusal(buyer, "chikimon", String(row.item || ""));
    if (_cr) return res.status(_cr.status).json(Object.assign({}, _cr.body, {
      error: `${_cr.body.error} — this listing was NOT consumed; if you have already paid, that payment is recorded against this listing and recoverable`,
      listingIntact: true }));
  }
  // CLAIM the sig BEFORE the async verify so two concurrent requests can't both settle it (TOCTOU),
  // BOUND to this listing so ONE payment can never settle a second listing. Released again if verify fails.
  _usedTxSigs.set(sig, { listingId: id, buyer, ts: Date.now() });
  // the buyer's ONE signed transaction must pay the correct 3-way split of real $CHIKI:
  // 75% to the seller, 20% to the reward pool, 5% burned (full price left the buyer)
  const split = await txMarketSplit(sig, buyer, sellerWallet, Number(row.price) || 0);
  if (!split.ok) { _usedTxSigs.delete(sig); return res.status(409).json({ error: `on-chain split for that signature failed: ${split.reason}` }); }
  // POST-AWAIT RE-CHECK — the double-buy TOCTOU (measured 2026-08-11, tpev_a_conservation A1):
  // two buyers with two DIFFERENT valid sigs both pass the pre-await find at the top of this route,
  // park in txMarketSplit together, and both used to settle — one creature granted twice, the
  // seller paid twice. The per-sig claim above cannot stop it (each buyer has their own sig).
  // Node resumes awaited handlers one at a time, and everything from THIS line to _consumeListing
  // runs synchronously — so re-finding the row here is atomic with consuming it: the first resumed
  // buyer consumes, the second finds nothing and is refused. The loser's verified payment is bound
  // to this listing by _usedTxSigs and recoverable through the existing lost-sale path — a wrong
  // payment is recoverable, a duplicated capped creature is not.
  if (!marketListings.some(x => x.id === id) || _soldListings.has(id))
    return res.status(409).json({ error: "another buyer completed this purchase first — the payment is recorded against this listing; contact support to recover it", soldOut: true });
  // ...AND THE SAME RE-CHECK FOR THE SATCHEL (2026-08-18 audit). The one-of-each gate at the top of
  // this route runs BEFORE `await txMarketSplit`, and the re-find above only re-reads the LISTING —
  // so two buys of the SAME species from two DIFFERENT sellers both passed the gate while empty,
  // both parked in the split, and both settled. MEASURED (satchel_attack_sim, section F): a buyer
  // holding zero fired two concurrent /market/buy-onchain against two healix listings and 2/2 got
  // past satchelCapRefusal (both then failed only on the dead RPC's split, not on the rule). The
  // answer is the one the double-buy TOCTOU directly above already chose, for the identical reason
  // it gives: everything from the re-find to _consumeListing runs synchronously, so re-asking HERE
  // is atomic with the transfer — "a wrong payment is recoverable, a duplicated capped creature is
  // not". The listing is left intact and the payment stays bound to it by _usedTxSigs.
  // ...AND ONLY THE ONE-OF-EACH ARM OF IT (2026-08-18 loss audit). The gate at the top of this route
  // runs before any money is committed and refuses for BOTH reasons, which is right — it is free
  // there. THIS one is downstream of a CONFIRMED on-chain payment, and the two reasons are not the
  // same kind of thing:
  //   * `duplicate` is a world-integrity violation. Two of one species on one wallet is the exact
  //     thing owner ruling 2 forbids, it cannot be undone, and it must be refused whatever it costs.
  //   * `satchel` (and `complete`, unreachable here because a named species that is not held cannot
  //     also be the whole catalog) is CAPACITY, and capacity has never been a scarcity rule in this
  //     file — every over-cap wallet in the game is grandfathered and keeps everything. Refusing for
  //     it here burns a real payment (75% already at the seller, 20% at the pool, 5% burned) to
  //     prevent a state the server tolerates everywhere else.
  // MEASURED (_aud3_lossline.mjs §L12): a Lv0 buyer holding 5 of a possible 6 fires two buys for two
  // DIFFERENT normals from two DIFFERENT sellers. Both clear the free gate (5 < 6, neither owned),
  // both pay, the first settles to 6, and the second reaches this line with code "satchel" — not
  // "duplicate". Under the old line that buyer's $CHIKI was gone with nothing to show for it.
  // This is nftSettleHandover's own stated rule, applied to the rail next door: "a settle always
  // completes and the buyer may land over their cap, grandfathered exactly like any other over-cap
  // holding". One over the cap is survivable; a burned payment is not.
  if (String(row.kind) === "chikimon") {
    const _cr2 = satchelCapRefusal(buyer, "chikimon", String(row.item || ""));
    if (_cr2 && _cr2.code === "duplicate") return res.status(_cr2.status).json(Object.assign({}, _cr2.body, {
      error: `${_cr2.body.error} — this listing was NOT consumed; your payment is recorded against it and recoverable`,
      listingIntact: true }));
    if (_cr2) console.warn(`satchel: ${buyer.slice(0, 8)} settles ${row.item} past its cap (${_cr2.body.held}/${_cr2.body.cap}) — paid on chain, grandfathered`);
  }
  // ESCROW SETTLE (CHIK_TP_ESCROW): capture the sold individual's uid from its reservation BEFORE
  // _consumeListing clears it — this is a permanent transfer, and the seller's registry row moves
  // to the buyer below (see tpeSettleChikimon). No-op field-read when the flag is off.
  const _tpeRes = (TP_ESCROW_ON && String(row.kind) === "chikimon") ? _tpeReservedUidFor(row.id) : null;
  marketListings = marketListings.filter(x => x.id !== id);
  _consumeListing(id);   // SOLD -> a re-push can never resurrect it
  const released = { id: row.id, kind: row.kind, item: row.item, qty: row.qty, lvl: row.lvl, xp: row.xp };
  // A VERIFIED grant: this line is only reached after txMarketSplit confirmed a real on-chain
  // $CHIKI split. It is what lets the ledger stamp the buyer's new unit "purchased" instead of
  // condemning every honest Trading Post buyer as unverified.
  recordAssetBuy(buyer, row.kind, row.item, row.lvl);
  // THE PERMANENT TRANSFER (CHIK_TP_ESCROW): a settled chikimon sale moves the seller's registry row
  // to the buyer and retires the seller's census ghost — so a capped species is counted ONCE, not
  // twice. Idempotent + crash-durable; no-op flag-off and for non-registry-backed goods.
  const _tpeMoved = (TP_ESCROW_ON && String(row.kind) === "chikimon")
    ? tpeSettleChikimon(sellerWallet, buyer, String(row.item || ""), _tpeRes ? _tpeRes.uid : "", row.id)
    : null;
  // AND THE SELLER'S RELEASE WHEN THE ROW DID NOT MOVE (see recordChikiSale). Only reached after
  // txMarketSplit confirmed a real split, so this is a disposal the SERVER witnessed — the one thing
  // chikiGone accepts. Skipped when the escrow already moved the row, because then regOwned has
  // dropped it by itself and a credit on top would be the laundering vector the clamp exists to stop.
  if (!_tpeMoved && String(row.kind) === "chikimon") recordChikiSale(sellerWallet, String(row.item || ""));
  // THE ACQUISITION BOUND. Reached only after txMarketSplit confirmed a real on-chain $CHIKI split,
  // so this is a settled sale: it counts against the seller's lifetime total, and the buyer genuinely
  // acquired the goods HERE, which is the strongest provenance a material can have.
  ownSold(sellerWallet, String(row.kind || "mat"), String(row.item || ""), Number(row.qty) || 0);
  ownCredit(buyer, String(row.kind || "mat"), String(row.item || ""), Number(row.qty) || 0);
  // same idem key as the soft rail — a listing settles exactly once on exactly one rail, and the
  // idempotent re-POST above (prior.released) returns before this line ever runs twice
  chronicleAdd("sale_onchain", sellerWallet, { sub: row.item, qty: Number(row.qty) || 0, val: Number(row.price) || 0,
    route: "/market/buy-onchain", idem: "sale:" + id,
    data: { kind: row.kind, buyer, sig, sellerNet: split.seller, teamTax: split.team },
    agg: [["salep:" + String(row.kind || "mat") + ":" + String(row.item || ""), Number(row.qty) || 0]] });
  _usedTxSigs.set(sig, { listingId: id, buyer, released, ts: Date.now() });   // cache release for idempotent retry
  saveUsedSigs();
  // record the sale so the SELLER'S client shows the on-chain proceeds landed
  const arr = marketSales[row.sid] || (marketSales[row.sid] = []);
  if (!arr.some(s => s.id === row.id)) arr.push({ id: row.id, item: row.item, kind: row.kind, qty: row.qty, price: row.price, buyer: buyer.slice(0, 8), buyerName, onchain: true, txSig: sig, sellerNet: split.seller, teamTax: split.team, ts: Date.now() });
  await saveMarket();
  res.json({ ok: true, released, txSig: sig });
});

// ---- ORDER settlement (real $CHIKI): the POSTER pays a pending delivery. Their ONE signed
// transaction must carry the same verified 75/20/5 split as a listing buy, with the FILLER in
// the seller seat. On verification: order closes, goods queue to the poster (fills poll), and
// the filler gets an on-chain sale receipt (sales poll — no soft credit, the money is real).
app.post("/market/order-pay", async (req, res) => {
  if (!MARKET_ONCHAIN) return res.status(503).json({ error: "on-chain trading is not enabled" });
  const b = req.body || {};
  const payer = String(b.payer || "");
  const sig = stripTags(String(b.txSig || "")).slice(0, 120);
  const id = stripTags(String(b.orderId || "")).slice(0, 40);
  if (!isPubkey(payer)) return res.status(400).json({ error: "valid payer wallet required" });
  if (!sig || !id) return res.status(400).json({ error: "txSig and orderId required" });
  if (_usedTxSigs.has(sig)) return res.status(409).json({ error: "that transaction was already used" });
  pruneMarket();
  const row = marketOrders.find(x => x.id === id);
  if (!row) return res.status(404).json({ error: "order is gone" });
  if (row.state !== "delivered" || !isPubkey(String(row.fillerWallet || ""))) return res.status(409).json({ error: "no delivery is awaiting payment on that order" });
  if (payer !== String(row.wallet || "")) return res.status(403).json({ error: "only the order's poster wallet can pay it" });
  // RESERVE the row: while `paying` is fresh, decline / undeliver / expiry are all refused, so
  // the order can't be torn down between tx broadcast and verification (money-goods atomicity)
  row.paying = Date.now();
  // CLAIM the sig BEFORE the async verify (TOCTOU) — one payment can never settle twice, BOUND to
  // this order so it can't be replayed against another. Pruned by age in saveUsedSigs, not by count.
  _usedTxSigs.set(sig, { orderId: id, buyer: payer, ts: Date.now() });
  // the client submits the sig the moment Phantom broadcasts, usually BEFORE the cluster reaches
  // 'confirmed' — a single lookup would routinely miss a perfectly good payment and strand real
  // $CHIKI. Poll for up to ~20s before giving up.
  let split = { ok: false, reason: "transaction not confirmed" };
  for (let tries = 0; tries < 8; tries++) {
    split = await txMarketSplit(sig, payer, String(row.fillerWallet), Number(row.price) || 0);
    if (split.ok || !/not confirmed|rpc error/i.test(String(split.reason || ""))) break;
    await new Promise(r => setTimeout(r, 2500));
  }
  if (!split.ok) { _usedTxSigs.delete(sig); delete row.paying; return res.status(409).json({ error: `on-chain split for that signature failed: ${split.reason} — if you approved it in Phantom, wait a few seconds and press Pay again (the same payment is retried, never re-charged)` }); }
  saveUsedSigs();
  // re-fetch: the reservation blocks decline/expiry, but never trust a 20s-old reference
  const fresh = marketOrders.find(x => x.id === id) || row;
  marketOrders = marketOrders.filter(x => x.id !== id);
  _consumeOrder(fresh.id);   // this id has now settled: it can never be posted again (see _soldOrders)
  // ---- THE OWNERSHIP BOOKKEEPING THE LISTING RAIL ALREADY DOES ----
  // /market/buy-onchain debits the seller and credits the buyer (ownSold + ownCredit, one line each).
  // This route did neither, in both directions. Seller half: a filler could stake the same fabricated
  // stockpile forever because `sold` never moved. Buyer half: a poster who paid real $CHIKI for 1,980
  // iron got no entitlement for it, so order-bought goods were unsellable beyond the allowance and
  // would be clamped out of the save the moment the v>=2 client ships.
  ownSold(String(fresh.fillerWallet || ""), String(fresh.kind || "mat"), String(fresh.item || ""), Number(fresh.qty) || 0);
  ownCredit(payer, String(fresh.kind || "mat"), String(fresh.item || ""), Number(fresh.qty) || 0);
  // the order id is what _soldOrders de-dupes on — the idem key for the whole 75/20/5 settlement
  chronicleAdd("order", String(fresh.fillerWallet || ""), { sub: fresh.item, qty: Number(fresh.qty) || 0,
    val: Number(fresh.price) || 0, route: "/market/order-pay", idem: "order:" + id,
    data: { kind: fresh.kind, payer, sig } });
  // goods to the POSTER (their client grants via the fills poll). Value-bearing: never cap-drop.
  // BOTH QUEUES STILL KEY ON THE ORDER ID, and they must: the filler's client matches this id
  // against its own my_deliveries record (Market.gd _deliv_done) and the poster's against its
  // orders_credited set, so a synthetic per-settlement id would leave an honest filler's delivery
  // showing "awaiting payment" forever. What made the shared key dangerous was that a settled id
  // could be POSTED AGAIN — that is what _consumeOrder above closes, at the source.
  const farr = marketFills[fresh.sid] || (marketFills[fresh.sid] = []);
  if (!farr.some(f => f.id === fresh.id))
    farr.push({ id: fresh.id, item: fresh.item, kind: fresh.kind, qty: fresh.qty, price: fresh.price, fillerName: fresh.fillerName || "a trainer", ts: Date.now() });
  // on-chain receipt to the FILLER (their client records it via the sales poll, no soft credit)
  const sarr = marketSales[fresh.fillerSid] || (marketSales[fresh.fillerSid] = []);
  if (!sarr.some(s => s.id === fresh.id))
    sarr.push({ id: fresh.id, item: fresh.item, kind: fresh.kind, qty: fresh.qty, price: fresh.price, buyer: payer.slice(0, 8), buyerName: fresh.buyer, onchain: true, txSig: sig, sellerNet: split.seller, teamTax: split.team, ts: Date.now() });
  await saveMarket();   // durability: the goods+receipt must be persisted before we confirm the pay
  res.json({ ok: true, txSig: sig });
});

// ---- Trading Post: a shared player-to-player market of in-game items for in-game $CHIKI.
// In-memory ring (persisted best-effort to kv). Items + soft-currency only — no on-chain funds.
// SETTLEMENT: when a listing is bought, the sale is RECORDED for the seller; the seller's
// client polls /market/sales and credits the price (minus the 5% burned market fee) to their
// purse, then acks. Nothing is credited twice and nothing vanishes on a lost response.
let marketListings = [];
let marketSales = {};                        // seller sid -> [ {id,item,kind,qty,price,buyer,ts} ]
let marketOrders = [];                       // WTB craft orders: {id, buyer, sid, kind, item, qty, price(total), ts}
let marketFills = {};                        // buyer sid -> [ {id,item,kind,qty,price,fillerName,ts} ] — goods owed to the buyer
let marketAuctions = [];                     // 🔨 chikimon auctions: {id, seller, sid, species, lvl, xp, minBid, curBid, curSid, curName, ts, endsAt}
let auctionRefunds = {};                     // sid -> [ {rid,id,amt,ts} ] — outbid escrow going home
// ---- HOW LONG A LISTING STANDS ON THE BOARD ---------------------------------------------------
// WAS 24 h, and that fuse is what emptied the Trading Post on 2026-08-07. Measured on the live board
// that day: 11 of 14 rows carried CREATION epochs of 2026-07-28..07-30 inside their ids (Market.gd
// mints "L%08x%d%03d" from a hash + Date.now()) but `ts` values 191 ms apart. So `ts` is when a row
// was last INSERTED, not when it was made — and a cohort of re-inserted rows therefore all dies in
// the same instant. Two things made that fatal:
//   1. an expiring row was dropped SILENTLY — no goods back, no receipt, nothing said to the seller;
//   2. a dropped row is re-pushed by its owner's client on the next sync (Market.gd's mine-reconcile),
//      which re-inserts the whole cohort under one shared timestamp — so the wipe repeats every 24 h.
// Both halves are closed below: expiry now hands the goods back and RETIRES the id (retireListing),
// so no row is ever silently dropped and no synchronised cohort can re-form. A week is the horizon a
// seller can plausibly be away for without the board pretending they never listed anything.
const MARKET_TTL_MS = 7 * 24 * 60 * 60 * 1000;   // a listing stands for a week, then the goods walk home
// ORDERS KEEP THE OLD 24 h HORIZON, deliberately. An order is a promise to pay real $CHIKI and the
// poster's balance was only checked at post time; stretching that promise to a week would let a
// filler stake goods against a wallet that emptied days ago. Split out so the listing horizon can
// move without touching the order book — order behaviour is byte-for-byte what it was.
const ORDER_TTL_MS = 24 * 60 * 60 * 1000;
// ---- ONE NUMBER FOR THE BOARD, BECAUSE TWO WAS A BUG ------------------------------------------
// The board held 400 rows, persisted 400 — and SERVED 300. Rows 301-400 from the end were on the
// board, in the database, with their sellers' goods escrowed against them, and invisible to every
// player including their owner (Market.gd builds its "have" set from what /market/list returns).
// Found by mkt_fix_sim §E, which measured 12 of seller 0's rows missing from a board that had only
// evicted 8. Cap, persist window and served window are now the same number, so a row is either on
// the board and visible, or it has been retired with its goods handed back — never a third state.
// If the real board ever approaches this, the answer is paging, not silent invisibility.
